import * as N3 from 'n3';
import { sourceBlankPrefix } from './parse.js';

const { namedNode, quad, defaultGraph } = N3.DataFactory;

const isTerm = (x) => Boolean(x) && typeof x.termType === 'string';
const isQuad = (x) => Boolean(x) && x.termType === 'Quad';

const WRITE_WRAPPERS = {
  addQuad: ({ store, buildQuad, route, report }) => (s, p, o, gr) => {
    const q = route(buildQuad(s, p, o, gr));
    const isNew = store.addQuad(q);
    if (isNew !== false) report([q], []);
    return isNew;
  },

  addQuads: ({ store, route, report }) => (quads) => {
    const added = [];
    for (const q0 of quads) {
      const q = route(q0);
      if (store.addQuad(q) !== false) added.push(q);
    }
    report(added, []);
  },

  removeQuad: ({ buildQuad, drop, report }) => (s, p, o, gr) => {
    const gone = drop(buildQuad(s, p, o, gr));
    if (gone) report([], [gone]);
    return Boolean(gone);
  },

  removeQuads: ({ drop, report }) => (quads) => {
    const removed = [];
    for (const q0 of quads) {
      const gone = drop(q0);
      if (gone) removed.push(gone);
    }
    report([], removed);
  },
};

export const ROUTED_METHODS = Object.keys(WRITE_WRAPPERS);

export const BLOCKED_METHODS = [
  'add', 'addAll', 'delete', 'deleteMatches', 'deleteGraph',
  'import', 'remove', 'removeMatches',
];

// Passed-through methods are bound to the STORE and the binding is cached, so
// calling one detached keeps working. Quads side-loaded onto the bare store sit
// in the default graph; routing removals blindly to the work graph leaves them
// standing.
export function editStore(store, { graph = null, onDelta = null, mintName = null } = {}) {
  const g = graph ? (isTerm(graph) ? graph : namedNode(String(graph))) : null;
  // The source's blank namespace, readable through the facade. A node minted for
  // this source has to be born inside it: the writer takes that prefix off again,
  // so a bare label would come back out as the label of some other node.
  const blankPrefix = sourceBlankPrefix(g);

  // A SOURCE THAT CANNOT CARRY A BLANK NODE gets a named one. The caller keeps
  // the blank term it minted, so the mapping is remembered: one name per node,
  // and a removal through the original term still finds its quad.
  const named = new Map();
  const nameOf = (term, q) => {
    if (!mintName || !term || term.termType !== 'BlankNode') return term;
    const known = named.get(term.value);
    if (known) return known;
    // ONLY A NODE BORN HERE. A blank node the source already carries belongs to
    // the source; naming it would put a renamed copy beside the original and
    // orphan everything that hangs off it. Such a write is refused further on.
    if (store.getQuads(term, null, null, null).length
      || store.getQuads(null, null, term, null).length) return term;
    const iri = mintName(term, q);
    if (!iri) return term;
    const fresh = namedNode(String(iri));
    named.set(term.value, fresh);
    return fresh;
  };
  // A removal only SUBSTITUTES names already handed out; it never mints. The
  // blank nodes that came in with the endpoint's own data must stay blank —
  // naming one there would invent a node the endpoint has never heard of.
  const swap = (term) => named.get(term && term.value) || term;
  const rewrite = (q, of) => {
    const s = of(q.subject, q);
    const o = of(q.object, q);
    return (s === q.subject && o === q.object) ? q : quad(s, q.predicate, o, q.graph);
  };

  const toGraph = (q) => (g && (!q.graph || q.graph.termType === 'DefaultGraph')
    ? quad(q.subject, q.predicate, q.object, g)
    : q);

  const route = (q) => toGraph(rewrite(q, nameOf));

  const drop = (q0) => {
    if (store.removeQuad(q0) !== false) return q0;
    const q = toGraph(rewrite(q0, swap));
    return (q !== q0 && store.removeQuad(q) !== false) ? q : null;
  };

  const report = (added, removed) => {
    if (onDelta && (added.length || removed.length)) onDelta({ added, removed });
  };

  const buildQuad = (s, p, o, gr) => (isQuad(s) && p === undefined
    ? s
    : quad(s, p, o, gr || defaultGraph()));

  const ctx = { store, route, drop, report, buildQuad };
  const wrap = Object.create(null);
  wrap.blankPrefix = blankPrefix;
  for (const name of ROUTED_METHODS) wrap[name] = WRITE_WRAPPERS[name](ctx);
  for (const name of BLOCKED_METHODS) {
    wrap[name] = () => {
      throw new Error(`edit store: store.${name}() bypasses the edit store `
        + '(no graph routing, no delta) — use addQuad/addQuads/removeQuad/removeQuads');
    };
  }

  const bound = new Map();

  return new Proxy(store, {
    get(target, prop) {
      if (prop in wrap) return wrap[prop];
      const v = Reflect.get(target, prop, target);
      if (typeof v !== 'function') return v;
      if (!bound.has(prop)) bound.set(prop, v.bind(target));
      return bound.get(prop);
    },
    set(target, prop, value) {
      return Reflect.set(target, prop, value, target);
    },
    has(target, prop) {
      return prop in wrap || prop in target;
    },
  });
}
