
import * as N3 from 'n3';

// Dedup keys on the TERM key including the graph: two quads that differ only in
// their graph are different quads, and keying on toString() gives
// "[object Object]" for every N3 quad, which cancels added against removed.
export function makeLog(store) {
  const done = [], undone = [];
  let groupDepth = 0;
  let pending = [];
  let nextId = 0;
  let pendingId = 0;

  const newStep = (deltas, id) => ({ id, deltas });

  const inverse = (d) => ({ added: d.removed, removed: d.added });

  const apply = (d) => {
    store.removeQuads(d.removed);
    store.addQuads(d.added);
  };

  const dedupeInverses = (allAdded, allRemoved) => {
    const key = (q) => N3.termToId(q.subject) + ' ' + N3.termToId(q.predicate)
      + ' ' + N3.termToId(q.object) + ' ' + N3.termToId(q.graph);

    const addedSet = new Set(allAdded.map(key));
    const removedSet = new Set(allRemoved.map(key));

    const net = (list, against) => {
      const seen = new Set();
      const out = [];
      for (const q of list) {
        const k = key(q);
        if (against.has(k) || seen.has(k)) continue;
        seen.add(k);
        out.push(q);
      }
      return out;
    };

    return {
      added: net(allAdded, removedSet),
      removed: net(allRemoved, addedSet),
    };
  };

  return {
    note(delta) {
      if (groupDepth > 0) {
        if (!pendingId) pendingId = ++nextId;
        pending.push(delta);
        return pendingId;
      }
      const id = ++nextId;
      done.push(newStep([delta], id));
      undone.length = 0;
      return id;
    },

    forgetLast() {
      if (groupDepth > 0) return pending.pop() !== undefined;
      return done.pop() !== undefined;
    },

    forgetStep(id) {
      if (!id) return false;
      if (groupDepth > 0 && id === pendingId) {
        if (!pending.length) return false;
        pending = [];
        pendingId = 0;
        return true;
      }
      const i = done.findIndex((s) => s.id === id);
      if (i < 0) return false;
      done.splice(i, 1);
      return true;
    },

    group(fn) {
      groupDepth++;
      try {
        fn();
      } catch (e) {
        if (pending.length > 0) {
          done.push(newStep([...pending], pendingId || ++nextId));
          undone.length = 0;
          pending = [];
          pendingId = 0;
        }
        throw e;
      } finally {
        groupDepth--;
        if (groupDepth === 0 && pending.length > 0) {
          done.push(newStep([...pending], pendingId || ++nextId));
          undone.length = 0;
          pending = [];
          pendingId = 0;
        }
        if (groupDepth === 0) pendingId = 0;
      }
    },

    undo() {
      const step = done.pop();
      if (!step) return null;

      undone.push(step);

      const allAdded = [];
      const allRemoved = [];

      for (const d of [...step.deltas].reverse()) {
        const inv = inverse(d);
        apply(inv);
        allAdded.push(...inv.added);
        allRemoved.push(...inv.removed);
      }

      return dedupeInverses(allAdded, allRemoved);
    },

    redo() {
      const step = undone.pop();
      if (!step) return null;

      done.push(step);

      const allAdded = [];
      const allRemoved = [];

      for (const d of step.deltas) {
        apply(d);
        allAdded.push(...d.added);
        allRemoved.push(...d.removed);
      }

      return dedupeInverses(allAdded, allRemoved);
    },

    canUndo: () => done.length > 0,
    canRedo: () => undone.length > 0,
  };
}
