// LAZY: nothing in the read viewer may import this module statically — an ordinary
// import in the edit chrome drags the whole edit layer into the entry chunk.
import { batch, createEffect, createRoot, createSignal, on, untrack } from 'solid-js';
import { editStore } from '../model/edit-store.js';
import { makeLog } from '../model/mutation-log.js';
import { makeSourceSync } from '../model/source-sync.js';
import { exportTurtle, groundName } from '../model/edit.js';
import { opfsWrite } from '../model/opfs.js';
import { sparqlUpdate, updateStatements } from '../model/sparql.js';
import { t } from '../model-boundary.js';
import type { Delta, Graph, Quad, Term } from '../model-boundary.js';
import { graph, invalidate, noteSyncedDelta } from './corpus.js';
import type { Invalidation } from './corpus.js';
import {
  editSource as layerEditSource, noWriteSourceKey, recoveryBusy, attachFlush,
} from './source-management.js';
import { clearNotice, clearRefusal, setRefusal, view, setNotice, setView } from './view.js';

export interface EditSource {
  graph: string;
  kind: 'ttl' | 'sparql';
  mode: 'read' | 'readwrite';
  opfs: string | null;
  name: string;
  url?: string;
  updateUrl?: string;
}

export interface SourceManagement {
  editSource: () => EditSource | null;
  attachFlush: (fn: ((source?: EditSource | null) => Promise<void>) | null) => void;
  recoveryBusy?: () => boolean;
}

export interface WriteStore {
  addQuad(...args: unknown[]): unknown;
  addQuads(quads: Quad[]): void;
  removeQuad(...args: unknown[]): unknown;
  removeQuads(quads: Quad[]): void;
  getQuads(s: unknown, p: unknown, o: unknown, g: unknown): Quad[];
  [key: string]: unknown;
}

const makeEditStore = editStore as unknown as (store: Graph, options: {
  graph?: string | null; onDelta?: ((d: Delta) => void) | null;
  mintName?: ((blank: unknown, q: Quad) => string) | null;
}) => WriteStore;

const mintFor = groundName as unknown as (g: Graph, q: Quad, base: string) => string;

export interface Notice { key: string; vars?: Record<string, unknown> }

const [offerOpen, setOfferOpen] = createSignal(false);
const [editNotice, setEditNotice] = createSignal<Notice | null>(null);
const [logVersion, setLogVersion] = createSignal(0);
const [lastInvalidation, setLastInvalidation] = createSignal<Invalidation | null>(null);
const [awaitingRecovery, setAwaitingRecovery] = createSignal(false);

export { offerOpen, lastInvalidation, editNotice as notice, noWriteSourceKey };

let sourceLayer: SourceManagement | null = null;
let disposeLink: (() => void) | null = null;

export function editSource(): EditSource | null {
  return sourceLayer ? sourceLayer.editSource() : null;
}

function recoveryRunning(): boolean {
  return !!(sourceLayer && sourceLayer.recoveryBusy && sourceLayer.recoveryBusy());
}

export const editMode = (): boolean => view.editMode;

function notify(key: string, vars?: Record<string, unknown>): void {
  setEditNotice({ key, vars });
  setNotice(key, vars);
}

function shortError(bericht: unknown): string {
  const s = String(bericht ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  return s.length > 160 ? `${s.slice(0, 160)}…` : s;
}

interface BareStore {
  addQuads(quads: Quad[]): void;
  removeQuads(quads: Quad[]): void;
  getQuads(s: Term | null, p: Term | null, o: Term | null, g: Term | null): Quad[];
}

interface Queue { process(delta: Delta): Promise<void>; flush(source?: EditSource): Promise<void> }

let facade: WriteStore | null = null;
let log: ReturnType<typeof makeLog> | null = null;
let sync: Queue | null = null;
let builtFor: { g: Graph | null; source: EditSource | null } = { g: null, source: null };

let pending: { added: Quad[]; removed: Quad[] } = { added: [], removed: [] };

// ONE GESTURE, ONE UPDATE. A mutation writes quad by quad, and a source that
// can refuse (an endpoint) must judge the whole gesture at once — otherwise its
// first quads are already stored when its last one is refused. While this stands
// the deltas are collected; the group hands them over as one.
let collecting: { added: Quad[]; removed: Quad[] } | null = null;

function noteForInvalidation(delta: Delta): void {
  if (delta.added && delta.added.length) pending.added.push(...delta.added);
  if (delta.removed && delta.removed.length) pending.removed.push(...delta.removed);
}

const stepOfQuad = new WeakMap<object, number>();

function rememberStep(delta: Delta, step: number): void {
  if (!step) return;
  for (const q of delta.added || []) stepOfQuad.set(q as object, step);
  for (const q of delta.removed || []) stepOfQuad.set(q as object, step);
}

function stepsOf(delta: Delta): number[] {
  const out = new Set<number>();
  for (const q of [...(delta.added || []), ...(delta.removed || [])]) {
    const step = stepOfQuad.get(q as object);
    if (step) out.add(step);
  }
  return [...out];
}

function forgetWriteSide(): void {
  facade = null;
  sync = null;
  builtFor = { g: null, source: null };
}

function rollBack(inverse: Delta): void {
  const bare = graph() as unknown as BareStore | null;
  if (bare) {
    bare.removeQuads(inverse.removed || []);
    bare.addQuads(inverse.added || []);
  }
  if (log) for (const step of stepsOf(inverse)) log.forgetStep(step);
  setLogVersion((v) => v + 1);
  noteForInvalidation(inverse);
}

function buildWriteSide(g: Graph, source: EditSource): void {
  if (!log || builtFor.g !== g) log = makeLog(g as unknown as BareStore);
  sync = makeSourceSync([source], {
    store: g,
    exportTurtle,
    opfsWrite,
    sparqlUpdate,
    updateStatements,
    onError: (b: EditSource | null, e: Error, inverse: Delta) => {
      rollBack(inverse);
      notify('src.updateError', {
        source: (b && (b.name || b.url)) || t('src.sourceUnknown'),
        error: shortError(e && e.message),
      });
      return rerenderAfterMutation();
    },
    onSynced: (_b: EditSource, delta: Delta) => noteSyncedDelta(delta),
    // A REFUSAL ANSWERS THE GESTURE, so it goes through the refusal channel: the
    // owner's next attempt clears it, where a report about the state stands.
    onRefuse: (_b: EditSource, count: number, inverse: Delta) => {
      rollBack(inverse);
      setRefusal('src.blankRefused', { n: count });
      setEditNotice({ key: 'src.blankRefused', vars: { n: count } });
      return rerenderAfterMutation();
    },
  }) as Queue;

  facade = makeEditStore(g, {
    graph: source.graph,
    // Only an endpoint needs it: a TTL source writes blank nodes out as blank
    // nodes and reads them back, so naming there would change the file for
    // nothing.
    mintName: source.kind === 'sparql' ? (_b, q) => mintFor(g, q, source.graph) : null,
    onDelta: (d: Delta) => {
      if (log) rememberStep(d, log.note(d) as number);
      setLogVersion((v) => v + 1);
      noteForInvalidation(d);
      if (collecting) {
        collecting.added.push(...(d.added || []));
        collecting.removed.push(...(d.removed || []));
        return;
      }
      if (sync) Promise.resolve(sync.process(d)).catch(() => {  });
    },
  });
  builtFor = { g, source };
}

export function writeStore(): WriteStore | null {
  const g = graph();
  const source = editSource();
  if (!g || !source) { forgetWriteSide(); return null; }
  if (!facade || builtFor.g !== g || builtFor.source !== source) buildWriteSide(g, source);
  return facade;
}

export function flushSource(source?: EditSource | null): Promise<void> {
  return sync ? sync.flush(source || undefined) : Promise.resolve();
}

// One effect for the confirm flow in BOTH directions; a call per site is how one
// gets forgotten. While the source layer reports it is still restoring, "no edit
// source" is a snapshot and not a judgement.
export function attachSourceManagement(next: SourceManagement | null): void {
  if (disposeLink) { disposeLink(); disposeLink = null; }
  if (sourceLayer) sourceLayer.attachFlush(null);
  sourceLayer = next;
  forgetWriteSide();
  if (!next) return;
  next.attachFlush(flushSource);
  createRoot((dispose) => {
    disposeLink = dispose;
    createEffect(on(() => next.editSource(), (source) => {
      forgetWriteSide();
      // THE CLAIM IS ABOUT THE STATE, and the state has changed. An `?edit=1`
      // deeplink states it before the owner has unlocked anything; left
      // standing it then reads as "your edit was not saved" over every write
      // that did land.
      if (source) {
        for (const key of ['edit.noWriteSource', 'edit.endpointNoWriteSource']) {
          clearNotice(key);
          if (editNotice()?.key === key) setEditNotice(null);
        }
      }
      if (source && (offerOpen() || awaitingRecovery())) {
        setAwaitingRecovery(false);
        setOfferOpen(false);
        setEditMode(true);
        return;
      }
      confirmEditMode();
    }));
    createEffect(() => {
      if (!awaitingRecovery()) return;
      if (next.recoveryBusy && next.recoveryBusy()) return;
      setAwaitingRecovery(false);
      untrack(() => setEditMode(true));
    });
  });
}

export function setEditMode(on: boolean, { confirm = true }: { confirm?: boolean } = {}):
boolean {
  const want = !!on;
  if (want && !editSource()) {
    if (recoveryRunning()) { setAwaitingRecovery(true); return false; }
    if (view.editMode) setView({ editMode: false });
    if (confirm) {
      setOfferOpen(true);
      notify(noWriteSourceKey());
    }
    return false;
  }
  if (view.editMode !== want) setView({ editMode: want });
  if (!want) setOfferOpen(false);
  return want;
}

export function confirmEditMode({ quiet = false }: { quiet?: boolean } = {}): void {
  if (!view.editMode || editSource()) return;
  if (recoveryRunning()) { setAwaitingRecovery(true); return; }
  setView({ editMode: false });
  if (!quiet) notify(noWriteSourceKey());
}

export function closeOffer(): void { setOfferOpen(false); }

export function quadsInEditSource(quads: Quad[]): boolean {
  const source = editSource();
  if (!source || !quads || !quads.length) return false;
  return quads.every((q) => q.graph && (q.graph as { value?: string }).value === source.graph);
}

export function editable(term: Term | string | null): boolean {
  const g = graph() as unknown as BareStore | null;
  const source = editSource();
  if (!g || !source || !term) return false;
  const t0 = typeof term === 'string'
    ? ({ termType: 'NamedNode', value: term, id: term } as Term) : term;
  return quadsInEditSource(g.getQuads(t0, null, null, null));
}

let rerenderRunning: Promise<void> | null = null;
let rerenderAgain = false;

// The invalidation only sets SIGNALS; what follows from them exists after the next
// task. That moment is what makes the execute promise usable for a caller that
// reads the DOM afterwards.
const tick = (): Promise<void> => new Promise((r) => { setTimeout(r, 0); });

async function rerenderNow(): Promise<void> {
  const delta = pending;
  if (!delta.added.length && !delta.removed.length) return;
  pending = { added: [], removed: [] };
  batch(() => { setLastInvalidation(invalidate(delta)); });
  await tick();
}

// The queue is ONE deep on purpose: mutations arrive in salvos and whoever mutates
// during a running round wants the end state, not every intermediate one.
function rerenderAfterMutation(): Promise<void> {
  if (rerenderRunning) { rerenderAgain = true; return rerenderRunning; }
  rerenderRunning = (async () => {
    try {
      do {
        rerenderAgain = false;
        await rerenderNow();
      } while (rerenderAgain);
    } finally {
      rerenderRunning = null;
      rerenderAgain = false;
    }
  })();
  return rerenderRunning;
}

export function execute(
  fn: (store: WriteStore) => void, { group = false }: { group?: boolean } = {},
): Promise<boolean> {
  const f = writeStore();
  if (!f) { notify(noWriteSourceKey()); return Promise.resolve(false); }
  // A FRESH ATTEMPT ANSWERS THE REFUSAL BEFORE IT: without this the "not saved"
  // of a refused attempt still stood over the save that followed it. Cleared
  // BEFORE the mutation, never after: what this one reports itself — a refusing
  // endpoint, a skipped triple — arrives later and must stay standing.
  clearRefusal();
  const outer = collecting;
  collecting = { added: [], removed: [] };
  try {
    batch(() => {
      if (group && log) log.group(() => fn(f)); else fn(f);
      setLogVersion((v) => v + 1);
    });
  } catch (e) {
    handOver(outer);
    setLogVersion((v) => v + 1);
    notify('edit.mutationError', { error: shortError(e instanceof Error ? e.message : e) });
    return rerenderAfterMutation().then(() => false, rerenderFailed);
  }
  handOver(outer);
  return rerenderAfterMutation().then(() => true, rerenderFailed);
}

function handOver(outer: { added: Quad[]; removed: Quad[] } | null): void {
  const d = collecting;
  collecting = outer;
  if (!d || (!d.added.length && !d.removed.length)) return;
  if (outer) {
    outer.added.push(...d.added);
    outer.removed.push(...d.removed);
    return;
  }
  if (sync) Promise.resolve(sync.process(d)).catch(() => {  });
}

function rerenderFailed(e: unknown): false {
  console.error('edit: the rebuild after a mutation bounced', e);
  notify('edit.mutationError', { error: shortError(e instanceof Error ? e.message : e) });
  return false;
}

export function canUndo(): boolean {
  void logVersion();
  return !!log && log.canUndo();
}

export function canRedo(): boolean {
  void logVersion();
  return !!log && log.canRedo();
}

async function applyHistory(direction: 'undo' | 'redo'): Promise<boolean> {
  writeStore();
  if (!log) return false;
  const delta: Delta | null = direction === 'undo' ? log.undo() : log.redo();
  setLogVersion((v) => v + 1);
  if (!delta) return false;
  noteForInvalidation(delta);
  if (sync) {
    try { await sync.process(delta); } catch {  }
  }
  await rerenderAfterMutation();
  return true;
}

export const undo = (): Promise<boolean> => applyHistory('undo');

export const redo = (): Promise<boolean> => applyHistory('redo');

export function resetEditState(): void {
  attachSourceManagement(null);
  setOfferOpen(false);
  setAwaitingRecovery(false);
  setEditNotice(null);
  setLastInvalidation(null);
  log = null;
  pending = { added: [], removed: [] };
  forgetWriteSide();
  if (view.editMode) setView({ editMode: false });
}

export function attachSourceLayer(): void {
  attachSourceManagement({ editSource: layerEditSource, recoveryBusy, attachFlush });
}

attachSourceLayer();
